# AFTER (slower): 16 configs, num_stages in {1,2,4}, BLOCK_SIZE in {256,512,1024,2048,4096,8192}
# Autotuner selected BLOCK_SIZE=128 (smallest), grid=6.29M, waves/SM=2978 -> regression
@triton.autotune(configs=[
    Config({'BLOCK_SIZE': 256},  num_warps=4,  num_stages=1),
    Config({'BLOCK_SIZE': 512},  num_warps=4,  num_stages=1),
    # ... 14 more configs spanning num_stages in {1,2,4} ...
    Config({'BLOCK_SIZE': 8192}, num_warps=16, num_stages=4),
], key=['n_elements'])
def tanh_kernel(...):
    offsets = block_start + tl.arange(0, BLOCK_SIZE)
    x = tl.load(input_ptr + offsets, mask=mask, eviction_policy='evict_first')
    y = libdevice.tanh(x)
    tl.store(output_ptr + offsets, y, mask=mask, eviction_policy='evict_first')
